package com.cooper.lithic.data.media.jpegworker;
import org.junit.Test;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executor;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import static org.junit.Assert.*;
public class JpegAbandonedDeliveryTest {
 @Test public void callbackIsOnlyQueuedAtCancellation(){List<Runnable> q=new ArrayList<>();AtomicInteger calls=new AtomicInteger();JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(q::add,v->calls.incrementAndGet(),e->{});assertTrue(d.abandon("v"));assertEquals(0,calls.get());assertEquals(JpegAbandonedDelivery.State.SCHEDULED,d.state());q.get(0).run();assertEquals(1,calls.get());assertEquals(JpegAbandonedDelivery.State.HANDLED,d.state());}
 @Test public void inactiveResultIsDeliveredExactlyOnce(){AtomicInteger calls=new AtomicInteger();JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(Runnable::run,v->calls.incrementAndGet(),e->{});assertTrue(d.abandon("v"));assertFalse(d.abandon("v"));assertEquals(1,calls.get());}
 @Test public void resumeCancellationAndInactiveObservationShareOnceClaim(){List<Runnable> q=new ArrayList<>();AtomicInteger calls=new AtomicInteger();JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(q::add,v->calls.incrementAndGet(),e->{});assertTrue(d.abandon("resume-cancel"));assertFalse(d.abandon("inactive"));q.get(0).run();assertEquals(1,calls.get());}
 @Test public void originalObjectIsPassedWithoutProofSynthesis(){Object unknown=new Object();AtomicReference<Object> seen=new AtomicReference<>();JpegAbandonedDelivery<Object> d=new JpegAbandonedDelivery<>(Runnable::run,seen::set,e->{});d.abandon(unknown);assertSame(unknown,seen.get());}
 @Test public void unknownTextCannotTurnIntoSuccess(){AtomicReference<String> seen=new AtomicReference<>();JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(Runnable::run,seen::set,e->{});d.abandon("RESULT_UNKNOWN");assertEquals("RESULT_UNKNOWN",seen.get());}
 @Test public void throwingHandlerRemainsFailed(){AtomicReference<Throwable> seen=new AtomicReference<>();JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(Runnable::run,v->{throw new IllegalStateException("persist");},seen::set);d.abandon("v");assertEquals(JpegAbandonedDelivery.State.FAILED,d.state());assertTrue(d.failure() instanceof IllegalStateException);assertSame(d.failure(),seen.get());}
 @Test public void failedHandlerIsNotRetriedAutomatically(){AtomicInteger calls=new AtomicInteger();JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(Runnable::run,v->{calls.incrementAndGet();throw new IllegalStateException();},e->{});d.abandon("v");assertFalse(d.abandon("v"));assertEquals(1,calls.get());}
 @Test public void executorRejectionIsUnknownNotHandled(){AtomicReference<Throwable> seen=new AtomicReference<>();JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(r->{throw new RejectedExecutionException();},v->fail("must not run"),seen::set);d.abandon("v");assertEquals(JpegAbandonedDelivery.State.FAILED,d.state());assertTrue(seen.get() instanceof RejectedExecutionException);}
 @Test public void observerFailureAlsoRemainsRecorded(){JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(Runnable::run,v->{throw new IllegalStateException();},e->{throw new UnsupportedOperationException();});d.abandon("v");assertEquals(JpegAbandonedDelivery.State.FAILED,d.state());assertTrue(d.failure() instanceof IllegalStateException);assertTrue(d.observerFailure() instanceof UnsupportedOperationException);}
 @Test public void concurrentAbandonmentQueuesOnlyOneCleanup() throws Exception {List<Runnable> q=java.util.Collections.synchronizedList(new ArrayList<>());AtomicInteger calls=new AtomicInteger();JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(q::add,v->calls.incrementAndGet(),e->{});Thread[] threads=new Thread[16];for(int n=0;n<threads.length;n++){threads[n]=new Thread(()->d.abandon("v"));threads[n].start();}for(Thread t:threads)t.join();assertEquals(1,q.size());q.get(0).run();assertEquals(1,calls.get());}
 @Test public void repeatedExecutorInvocationStillOnlyRunsHandlerOnce(){AtomicReference<Runnable> task=new AtomicReference<>();AtomicInteger calls=new AtomicInteger();JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(task::set,v->calls.incrementAndGet(),e->{});d.abandon("v");task.get().run();task.get().run();assertEquals(1,calls.get());}
 @Test public void noAbandonmentCreatesNoWork(){AtomicInteger scheduled=new AtomicInteger();JpegAbandonedDelivery<String> d=new JpegAbandonedDelivery<>(r->scheduled.incrementAndGet(),v->fail("unoffered"),e->{});assertEquals(0,scheduled.get());assertEquals(JpegAbandonedDelivery.State.IDLE,d.state());}
}
